// ❌ OLD: If a developer imports a helper from this file into a
// 'use client' component, the bundler will attempt to bundle it, leaking
// DB_SECRET or causing undefined environment variable runtime crashes.
export const db = new DatabaseClient(process.env.DB_SECRET!);

export async function getUser(id: string) {
